package com.bank.deploy;

import java.util.logging.Logger;

public class BlueGreenStrategy implements DeploymentStrategy {
    private static final Logger log = Logger.getLogger(BlueGreenStrategy.class.getName());
    private String bluePrevious;

    @Override public String name() { return "Blue-Green"; }

    @Override public void deploy(String service, String newVersion) {
        log.info(() -> "[Blue-Green] " + service + ": deploy GREEN=" + newVersion
            + " alongside BLUE; test green with 0% live traffic.");
        bluePrevious = "previous-" + service;
        log.info(() -> "[Blue-Green] " + service + ": FLIP 100% traffic BLUE→GREEN at once.");
        log.info(() -> "[Blue-Green] " + service + ": keep BLUE warm for INSTANT rollback.");
    }

    @Override public void rollback(String service) {
        log.warning(() -> "[Blue-Green] " + service + ": FLIP back to BLUE instantly ("
            + bluePrevious + ") — zero-wait rollback.");
    }
}
