package com.bank.deploy;

import java.util.logging.Logger;

public class CanaryStrategy implements DeploymentStrategy {
    private static final Logger log = Logger.getLogger(CanaryStrategy.class.getName());
    private final int[] steps = {1, 10, 50, 100};
    private boolean regressionAt50;   // simulate a metric regression

    public CanaryStrategy(boolean regressionAt50) { this.regressionAt50 = regressionAt50; }

    @Override public String name() { return "Canary"; }

    @Override public void deploy(String service, String newVersion) {
        for (int pct : steps) {
            if (regressionAt50 && pct == 50) {
                log.severe(() -> "[Canary] " + service + ": metrics REGRESSED at 50% — ABORT.");
                rollback(service);
                return;
            }
            log.info(() -> "[Canary] " + service + ": shift " + pct + "% to " + newVersion
                + "; watch error-rate/latency.");
        }
        log.info(() -> "[Canary] " + service + ": healthy at every step → promoted to 100%.");
    }

    @Override public void rollback(String service) {
        log.warning(() -> "[Canary] " + service + ": route 100% back to STABLE — only the "
            + "canary slice was ever exposed.");
    }
}
