package com.bank.deploy;

import java.util.logging.Logger;

public class RollingStrategy implements DeploymentStrategy {
    private static final Logger log = Logger.getLogger(RollingStrategy.class.getName());
    private final int totalInstances;
    private final int batchSize;      // maxSurge-like

    public RollingStrategy(int totalInstances, int batchSize) {
        this.totalInstances = totalInstances;
        this.batchSize = batchSize;
    }

    @Override public String name() { return "Rolling"; }

    @Override public void deploy(String service, String newVersion) {
        int done = 0;
        while (done < totalInstances) {
            int batch = Math.min(batchSize, totalInstances - done);
            done += batch;
            final int updated = done;
            log.info(() -> "[Rolling] " + service + ": replaced " + updated + "/" + totalInstances
                + " with " + newVersion + " (old+new mix — needs backward compat).");
        }
        log.info(() -> "[Rolling] " + service + ": all instances on " + newVersion
            + " — no extra environment used.");
    }

    @Override public void rollback(String service) {
        log.warning(() -> "[Rolling] " + service + ": rolling BACK a few at a time — "
            + "slower than a blue-green flip.");
    }
}
