package com.bank.deploy;

import java.util.logging.Logger;

public class DeploymentCoordinator {
    private static final Logger log = Logger.getLogger(DeploymentCoordinator.class.getName());

    public void release(DeploymentStrategy strategy, String service, String version) {
        log.info(() -> "Releasing " + service + " " + version + " via " + strategy.name());
        strategy.deploy(service, version);
    }
}
