package com.bank.deploy;

import java.util.logging.*;

public class DeploymentStrategyDemo {
    private static final Logger log = Logger.getLogger(DeploymentStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DeploymentCoordinator coordinator = new DeploymentCoordinator();

        // Critical payments → Blue-Green (instant rollback).
        coordinator.release(new BlueGreenStrategy(), "payments-service", "3.0.0");

        // Risky fraud model → Canary that regresses at 50% and aborts.
        coordinator.release(new CanaryStrategy(true), "fraud-scoring", "2.0.0");

        // Routine account query → Rolling (6 instances, 2 at a time).
        coordinator.release(new RollingStrategy(6, 2), "account-query", "1.5.0");
    }
}
